#ifndef DISPLAY_H
#define DISPLAY_H

#include <stdint.h>

// Screen Dimensions
#define VGA_WIDTH        320
#define VGA_HEIGHT       240

// the color codes for the VGA screen 8bits RGB
// Hex code generated by AI
#define COLOR_BLACK          0x00
#define COLOR_WHITE          0xFF
#define COLOR_RED            0xE0
#define COLOR_GRAY           0x6D  
#define COLOR_DARKGRAY       0x34   
#define COLOR_LIGHTGRAY      0xD6  
#define COLOR_BLUE           0x03  
#define COLOR_YELLOW         0xFC  
#define COLOR_GREEN          0x1C  
#define COLOR_DARKGREEN      0x0C  
#define COLOR_BROWN          0x80  
#define COLOR_PARKING_ZONE   0xFC

// Memory mapped VGA Hardware Registers
#define vgaBuffer        ((volatile uint32_t*) 0x04000100) 
#define vgaBackbuffer    ((volatile uint32_t*) 0x04000104) 
#define vgaStatusReg     ((volatile uint32_t*) 0x0400010C) 

// Framebuffer Memory Addresses
#define frame_1          0x08000000                         
#define frame_2          (frame_1 + VGA_WIDTH * VGA_HEIGHT) 

// Function Prototypes
void init_vga(void);
void bufferSwap(void);
volatile uint8_t *backBuffer(void);
void clear_screen(int color);
void draw_pixel(int x, int y, int color);
void draw_rect(int x, int y, int width, int height, int color);
void draw_circle(int x0, int y0, int radius, int color);
void draw_car(int x, int y, int angle, int body_color);
void draw_wall(int x, int y, int width, int height);
void draw_tree(int x, int y, int radius);
void draw_level_outlines();

#endif

